<?php if (!$properties): ?><div class="empty">Ainda não há imóveis publicados.</div><?php else: ?><div class="property-grid"><?php foreach ($properties as $property): ?><article class="property-card"><div class="property-image">LarPerto</div><div class="property-body"><span class="tag"><?= Helper::e(ucfirst($property['finalidade'])) ?></span><h3><a href="<?= Helper::e(Helper::url('imovel/' . $property['slug'])) ?>"><?= Helper::e($property['titulo']) ?></a></h3><p class="muted"><?= Helper::e($property['bairro'] ?: $property['cidade']) ?>, <?= Helper::e($property['cidade']) ?>-GO</p><strong class="price"><?= Helper::e(Helper::formatPrice($property['preco'])) ?><?= $property['finalidade'] === 'aluguel' ? ' / mês' : '' ?></strong><p class="features"><?= (int) $property['quartos'] ?> quartos · <?= (int) $property['banheiros'] ?> banheiros · <?= (int) $property['vagas'] ?> vagas</p></div></article><?php endforeach; ?></div><?php endif; ?>